yaml:
name: PR Status Labeler

on:
  workflow_run:
    workflows: ["Capture PR Data"]
    types:
      - completed

permissions:
  pull-requests: write
  contents: read

jobs:
  label-pr:
    if: ${{ github.event.workflow_run.conclusion == 'success' }}
    runs-on: ubuntu-latest
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4
        with:
          fetch-depth: 0

      - name: Download PR data artifact
        uses: actions/download-artifact@v4
        with:
          name: pr-data
          path: .

      - name: Apply labels to PR
        uses: actions/github-script@v6
        with:
          script: |
            const fs = require('fs');
            const data = JSON.parse(fs.readFileSync('pr-data.json', 'utf8'));
            const prNumber = data.number;
            const labelsToAdd = ['auto-label'];
            const headRepo = github.event.workflow_run.head_repository.full_name;
            const baseRepo = `${context.repo.owner}/${context.repo.repo}`;
            if (headRepo !== baseRepo) {
              labelsToAdd.push('fork');
            }
            await github.rest.issues.addLabels({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: prNumber,
              labels: labelsToAdd
            });
